#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-coverage-threshold.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-coverage-threshold — refuses a vitest config that does not gate
 * coverage at 100% per-file (UNIT_COVERAGE.yaml.coverage).
 *
 * The gap this closes: `pnpm test:coverage` runs, but nothing confirms the
 * project's vitest config actually SETS `coverage.thresholds` to 100 with
 * `perFile: true`. A silently-lowered or absent threshold lets the coverage
 * run pass green forever while every downstream "100% coverage" claim becomes
 * a lie. UNIT_COVERAGE.yaml is explicit: "an unconfigured threshold is a
 * defect, not a pass."
 *
 * What it checks — for every vitest config in the repo (vitest.config.*, and
 * vite.config.* that carries a `test`+`coverage` block):
 *   1. a `coverage.thresholds` block exists,
 *   2. it demands 100 on all metrics — either the `100: true` shorthand OR
 *      explicit lines/branches/functions/statements all = 100,
 *   3. `perFile: true` is set (aggregate 100% can hide a 0%-covered file).
 *
 * Scope / honesty: this is a static config-shape gate. It catches the absent /
 * lowered / non-perFile threshold — the flagged failure. It does NOT re-run
 * coverage (that is `pnpm test:coverage`'s job); it verifies the bar the run
 * enforces is actually set to 100 perFile.
 *
 * No-op green when the repo uses no vitest config (nothing to gate yet).
 *
 * Usage: node scripts/verify/verify-coverage-threshold.mjs [<repo-root>]
 * Exits 0 when every vitest config gates 100 perFile (or none exist); 1 otherwise.
 */
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative, basename } from "node:path";

const REPO_ROOT = process.argv[2] || process.cwd();
const NAME = "verify-coverage-threshold";
const IGNORE = new Set(["node_modules", ".git", ".next", ".turbo", "dist", "build", "out", "coverage", ".vercel", "test-results", "playwright-report"]);
const CONFIG_RE = /^(vitest|vite)\.config\.[mc]?[jt]s$/;

function findConfigs(dir, acc = []) {
  let entries;
  try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return acc; }
  for (const e of entries) {
    if (IGNORE.has(e.name)) continue;
    const p = join(dir, e.name);
    if (e.isDirectory()) findConfigs(p, acc);
    else if (e.isFile() && CONFIG_RE.test(e.name)) acc.push(p);
  }
  return acc;
}

// Is this file a vitest config we should gate? vitest.config.* always; vite.config.*
// only when it carries a test block that references coverage (otherwise it's just a
// build config and coverage lives elsewhere).
function isVitestConfig(file, text) {
  if (basename(file).startsWith("vitest.config")) return true;
  return /\btest\s*:/.test(text) && /\bcoverage\s*:/.test(text);
}

// Heuristic threshold check over the config text.
function checkThresholds(text) {
  const problems = [];
  const tIdx = text.search(/\bthresholds\s*:/);
  if (tIdx === -1) {
    return ["no `coverage.thresholds` block — coverage is ungated (UNIT_COVERAGE requires 100 perFile)"];
  }
  const win = text.slice(tIdx, tIdx + 600);
  const shorthand100 = /\b100\s*:\s*true/.test(win);
  const metrics = ["lines", "branches", "functions", "statements"];
  const explicit100 = metrics.every((m) => new RegExp(`\\b${m}\\s*:\\s*100\\b`).test(win));
  if (!shorthand100 && !explicit100) {
    problems.push("thresholds do not demand 100 on all metrics (need `100: true` or lines/branches/functions/statements all = 100)");
  }
  // perFile may sit on coverage or inside thresholds — accept either, scan whole text.
  if (!/\bperFile\s*:\s*true/.test(text)) {
    problems.push("`perFile: true` not set — aggregate 100% can hide a 0%-covered file");
  }
  return problems;
}

const configs = findConfigs(REPO_ROOT).filter((f) => {
  try { return statSync(f).isFile(); } catch { return false; }
});

const gated = [];
const violations = [];
for (const file of configs) {
  let text = "";
  try { text = readFileSync(file, "utf8"); } catch { continue; }
  if (!isVitestConfig(file, text)) continue;
  const problems = checkThresholds(text);
  gated.push(file);
  if (problems.length) {
    for (const p of problems) violations.push(`${relative(REPO_ROOT, file)}: ${p}`);
  }
}

if (gated.length === 0) {
  process.stdout.write(`✅ ${NAME} — no vitest config in this repo; nothing to gate.\n`);
  process.exit(0);
}
if (violations.length === 0) {
  process.stdout.write(`✅ ${NAME} — ${gated.length} vitest config(s) gate coverage at 100% perFile.\n`);
  process.exit(0);
}
process.stderr.write(`\n❌ ${NAME}: ${violations.length} coverage-threshold violation(s)\n`);
for (const v of violations) process.stderr.write(`   - ${v}\n`);
process.stderr.write(`\n   Fix: set coverage.thresholds to 100 (or \`100: true\`) with perFile:true in the vitest config. UNIT_COVERAGE.yaml.coverage.\n`);
process.exit(1);
